#!/usr/bin/env python3
"""Compare every generated byte to a pinned accepted Linux reference."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import sys

ROOT=Path(__file__).resolve().parents[1]
CLOCK=rb'\d{2}:\d{2}:\d{2} on \d{2}/\d{2}/\d{2}'
MODEL=re.compile(rb'(Model run at )('+CLOCK+rb')')
NORMAL=re.compile(rb'(Normal termination at )('+CLOCK+rb')')
CPU=re.compile(rb'(?m)^(  Total CPU runtime    = )([0-9.]+)( min\r?$)')
BUILD=re.compile(rb'(CE-QUAL-W2 Version compile date:)([A-Z][a-z]{2} [ 0-3][0-9] \d{4} \d{2}:\d{2}:\d{2})')

def safe(path):
    path=Path(path)
    if path.name.lower()=='debug.log' or path.is_symlink() or not path.is_file():
        raise ValueError('Excluded or nonregular evidence file: '+str(path))
    return path

def digest(path):
    path=safe(path)
    with path.open('rb') as stream:value=hashlib.file_digest(stream,'sha256').hexdigest()
    return {'bytes':path.stat().st_size,'sha256':value}

def canonical(path,name):
    path=safe(path);rawhash=hashlib.sha256();normalhash=hashlib.sha256();size=0;normal_size=0;counts={}
    if name.lower().endswith('.w2l'):
        with path.open('rb') as stream:
            stream.seek(724);clock=stream.read(72)
        if len(clock)!=72 or not re.fullmatch(rb'Model run at '+CLOCK+rb' +',clock):
            raise ValueError('Unrecognized W2L TITLE(11) clock field')
        counts['TITLE(11)']=1
        with path.open('rb') as stream:
            for raw in iter(lambda:stream.read(1024*1024),b''):
                rawhash.update(raw);normal=bytearray(raw)
                lo=max(724-size,0);hi=min(796-size,len(normal))
                if lo<hi:normal[lo:hi]=b'CLOCK-EXCLUDED'.ljust(72)[size+lo-724:size+hi-724]
                normalhash.update(normal);size+=len(raw);normal_size+=len(normal)
    else:
        rules=[]
        if re.fullmatch(r'snp\d*\.opt',name):rules=[('model_clock',MODEL),('termination_clock',NORMAL),('cpu_runtime',CPU)]
        elif re.fullmatch(r'cpl\d*\.opt',name) or name=='prf.opt':rules=[('model_clock',MODEL)]
        elif name=='W2CodeCompilerVersion.opt':rules=[('compile_timestamp',BUILD)]
        with path.open('rb') as stream:
            chunks=stream if rules else iter(lambda:stream.read(1024*1024),b'')
            for raw in chunks:
                rawhash.update(raw);normal=raw
                for label,pattern in rules:
                    count=len(pattern.findall(normal))
                    if count:
                        counts[label]=counts.get(label,0)+count
                        normal=pattern.sub(lambda m:m[1]+b'<EXCLUDED>'+(m[3] if m.lastindex==3 else b''),normal)
                normalhash.update(normal);size+=len(raw);normal_size+=len(normal)
    return {'raw':{'bytes':size,'sha256':rawhash.hexdigest()},
            'normalized':{'bytes':normal_size,'sha256':normalhash.hexdigest()},'excluded_counts':counts}

def verify(run,profile):
    run=Path(run).resolve();case_run=run/'case';model=case_run/'model'
    result=json.loads((run/'run-result.json').read_text())
    if result['profile']!=profile:raise ValueError('Explicit validation profile differs from run')
    case=result['case'];references=json.loads((ROOT/'config/accepted-output-controls.json').read_text())
    expected=references['profiles'][profile][case]
    cap=json.loads((case_run/'capture.json').read_text());stage=json.loads((case_run/'staging.json').read_text())
    errors=[]
    if cap['exit_code']!=expected['exit_code'] or result['actual_model_exit']!=cap['exit_code']:
        errors.append('Native exit differs from pinned reference or wrapper receipt')
    if result['verification_errors']:errors.append('Run wrapper reported verification errors')
    expected_wrapper=cap['exit_code'] if cap['exit_code']>=0 else 128-cap['exit_code']
    if result['wrapper_exit']!=expected_wrapper:errors.append('Wrapper did not preserve native result')
    if profile=='windows-compatible-invalid-only':
        from verify_fp_receipt import verify as verify_fp
        fp=verify_fp(case_run)
        if not fp['normal_return_and_post_close_guard_confirmed_by_zero_exit']:errors.append('Compatibility FP completion unconfirmed')
    if stage['inputs']!=expected['inputs'] or cap['changed_or_missing_inputs']:
        errors.append('Pinned inputs or input-preservation receipt differ')
    if digest(case_run/'run-start.json')!=cap['run_start_record']:errors.append('Run-start receipt changed')
    for name,record in cap['execution_records'].items():
        if Path(name).name!=name or digest(case_run/name)!=record:errors.append('Execution receipt changed: '+name)
    paths={}
    for path in model.rglob('*'):
        if path.is_symlink():raise ValueError('Symlinked model output')
        if path.is_file():paths[path.relative_to(model).as_posix()]=path
    for name,record in expected['inputs'].items():
        if name not in paths or digest(paths[name])!=record:errors.append('Input bytes changed: '+name)
    output_names=set(paths)-set(expected['inputs'])
    if output_names!=set(expected['outputs']) or output_names!=set(cap['outputs']):
        errors.append('Full generated output inventory differs')
    files={}
    for name in sorted(output_names|set(expected['outputs'])):
        if name not in output_names or name not in expected['outputs']:
            files[name]={'classification':'missing_or_extra'};continue
        actual=canonical(paths[name],name);want=expected['outputs'][name]
        if actual['raw']!=cap['outputs'][name]:errors.append('Captured output hash changed: '+name)
        classification=('byte_identical' if actual['raw']==want['raw'] else
                        'established_clock_only' if actual['normalized']==want['normalized'] and actual['excluded_counts']==want['excluded_counts'] else 'unexplained_difference')
        if classification=='unexplained_difference':errors.append('Output differs: '+name)
        files[name]={'classification':classification,'actual':actual,'expected':want}
    if cap['exit_code']==-6:
        stderr=(case_run/'stderr.txt').read_text(errors='replace')
        if 'forrtl: error (65): floating invalid' not in stderr or not re.search(r'\bcalculate_tke\s+100\s+az\.f90\b',stderr):
            errors.append('Expected strict Detroit error65 at calculate_tke / az.f90:100 not recorded')
    return {'format':'cequal-output-regression-v1','profile':profile,'case':case,'pass':not errors,
        'errors':errors,'files':files,'native_exit':cap['exit_code'],'expected_exit':expected['exit_code'],
        'scope':'Every generated byte and input; only pinned run/build clock fields excluded. No floating tolerance or line-ending normalization.',
        'reference_evidence':expected['evidence'],'target_qualification':'Records actual execution host; this check alone does not assert Ubuntu was used.'}

def main():
    if sys.flags.optimize:raise ValueError('Python optimization is not allowed for validated comparisons')
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--profile',choices=('strict','windows-compatible-invalid-only'),default='strict')
    p.add_argument('--run-dir',type=Path,required=True);p.add_argument('--report',type=Path,required=True)
    a=p.parse_args();report=verify(a.run_dir,a.profile)
    with a.report.open('x') as stream:json.dump(report,stream,indent=2);stream.write('\n')
    print(json.dumps({'pass':report['pass'],'profile':a.profile,'case':report['case'],'outputs':len(report['files']),'errors':report['errors']}))
    return 0 if report['pass'] else 1

if __name__=='__main__':
    try:sys.exit(main())
    except (OSError,ValueError,KeyError,AssertionError) as error:
        print('VALIDATION STOPPED: '+str(error),file=sys.stderr);sys.exit(2)
